/* quick lookups ---------------------------------------------------------- */
export const catById       = id => MASTER.cats.find(c => c.id === id)
export const areaById      = id => MASTER.areas.find(a => a.id === id)
export const checklistById = id => MASTER.checklists.find(c => c.id === id)
export const equipInCat    = cat => MASTER.equipment.filter(e => e.cat === cat)
export const areasInCat    = cat => MASTER.areas.filter(a => a.cat === cat)
export const checklistTaskCount = cl => (cl?.groups || []).reduce((s, g) => s + g.tasks.length, 0)
